ws_run_block 50 'Deploying the AI agent to AgentCore Runtime' '6. Create the AgentCore Runtime, or update it if it exists. The application reads its configuration from environment variables, so the runtime gets the values from ~/environment/.envrc:' 2127 2149 'bash' 'python-strands' 300 <<'WS_TEST_BLOCK_1000_50'
source ~/environment/.envrc
ECR_URI="${ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com/aiagent"

RUNTIME_CONFIG=(
  --role-arn "arn:aws:iam::${ACCOUNT_ID}:role/aiagent-runtime-role"
  --agent-runtime-artifact "{\"containerConfiguration\":{\"containerUri\":\"${ECR_URI}:latest\"}}"
  --authorizer-configuration "{\"customJWTAuthorizer\":{\"discoveryUrl\":\"${AIAGENT_DISCOVERY_URL}\",\"allowedClients\":[\"${AIAGENT_CLIENT_ID}\"]}}"
  --request-header-configuration '{"requestHeaderAllowlist":["Authorization"]}'
  --environment-variables "AGENTCORE_MEMORY_ID=${AGENTCORE_MEMORY_ID},KNOWLEDGE_BASE_ID=${KNOWLEDGE_BASE_ID},GATEWAY_URL=${GATEWAY_URL},COGNITO_ISSUER_URI=${COGNITO_ISSUER_URI},ARTIFACTS_BUCKET=${ARTIFACTS_BUCKET},PORTAL_URL=${PORTAL_URL},OTEL_PYTHON_DISABLED_INSTRUMENTATIONS=aws_mcp"
  --network-configuration "{\"networkMode\":\"VPC\",\"networkModeConfig\":{\"subnets\":[\"${SUBNET_ID}\"],\"securityGroups\":[\"${SG_ID}\"]}}"
  --region ${AWS_REGION} --no-cli-pager
)

