ws_run_block 2 'Creating the policies' '2. Define a shell function that creates a policy, or updates it when it exists. Use the same terminal for the rest of the module:' 67 80 'bash' '' <<'WS_TEST_BLOCK_1600_2'
put_policy() {  # put_policy NAME CEDAR_STATEMENT
  local id definition
  id=$(aws bedrock-agentcore-control list-policies --policy-engine-id "${POLICY_ENGINE_ID}" --no-cli-pager \
    --query "policies[?name=='$1'].policyId | [0]" --output text)
  definition=$(jq -n --arg s "$2" '{policy: {statement: $s}}')
  if [ "${id}" = "None" ]; then
    aws bedrock-agentcore-control create-policy --policy-engine-id "${POLICY_ENGINE_ID}" --name "$1" \
      --definition "${definition}" --validation-mode IGNORE_ALL_FINDINGS --no-cli-pager > /dev/null
  else
    aws bedrock-agentcore-control update-policy --policy-engine-id "${POLICY_ENGINE_ID}" --policy-id "${id}" \
      --definition "${definition}" --validation-mode IGNORE_ALL_FINDINGS --no-cli-pager > /dev/null
  fi
  echo "$1"
}
WS_TEST_BLOCK_1600_2

