ws_run_block 8 'Managing the prompt in a configuration bundle' '2. Replace the content of main.py:' 218 360 'python' 'python-strands' <<'WS_TEST_BLOCK_1900_8'
cat <<'EOF' > ~/environment/aiagent/main.py
from datetime import datetime
import os

import boto3
from bedrock_agentcore.memory.integrations.strands.config import AgentCoreMemoryConfig, RetrievalConfig
from bedrock_agentcore.memory.integrations.strands.session_manager import AgentCoreMemorySessionManager
from bedrock_agentcore.runtime import BedrockAgentCoreApp
from starlette.staticfiles import StaticFiles
from strands import Agent
from strands.models.bedrock import BedrockModel

import auth
import artifacts
from browser_tools import browse_url, take_screenshot
import attachments
import guardrail
from code_interpreter_tools import execute_code
from knowledge import search_knowledge_base
import mcp_tools
from mcp_tools import gateway_tools
import compliance_tools
import calendar_tools
import prompt_config
from strands.hooks.events import BeforeModelCallEvent

app = BedrockAgentCoreApp()
log = app.logger
app.add_middleware(auth.JwtAuthMiddleware)

model = BedrockModel(model_id="global.anthropic.claude-sonnet-4-6", max_tokens=4096, temperature=0.7,
                     **guardrail.model_config())

SYSTEM_PROMPT = """
You are the travel and expense assistant of the company. You help employees plan business trips,
follow the travel and expense policies, and keep track of their trips and expenses.

Rules:
- Focus on business travel and expenses.
- Ask for missing details such as dates, origin, or destination instead of guessing them.
- Do not invent policy rules; say so when you are not sure.

Format:
- Be friendly and concise.
- Use tables to compare options.
"""
SYSTEM_PROMPT += f"\nFlight and hotel offers: the corporate travel portal {os.environ['PORTAL_URL']}\n"

MEMORY_ID = os.environ["AGENTCORE_MEMORY_ID"]
REGION = os.environ.get("AWS_REGION") or boto3.session.Session().region_name


def discover_namespaces():
    control = boto3.client("bedrock-agentcore-control", region_name=REGION)
    memory = control.get_memory(memoryId=MEMORY_ID)["memory"]
    return [(s["strategyId"], ns) for s in memory.get("strategies", []) for ns in s["namespaces"]]


NAMESPACES = discover_namespaces()
log.info("Discovered %d LTM namespaces", len(NAMESPACES))


def memory_session_manager(conversation_id):
    actor_id, _, session_id = conversation_id.partition(":")
    retrieval = {
        ns.replace("{memoryStrategyId}", strategy_id).replace("{actorId}", actor_id):
            RetrievalConfig(top_k=3, relevance_score=0.2)
        for strategy_id, ns in NAMESPACES
    }
    config = AgentCoreMemoryConfig(
        memory_id=MEMORY_ID,
        actor_id=actor_id,
        session_id=session_id or "default-session",
        retrieval_config=retrieval,
    )
    return AgentCoreMemorySessionManager(config, REGION)


TOOLS = [
    search_knowledge_base,
    browse_url,
    take_screenshot,
    execute_code,
]
TOOLS += gateway_tools()
log.info("MCP tools enabled: %s", bool(os.environ.get("GATEWAY_URL")))
if compliance_tools.AUDITOR_HARNESS_ARN:
    TOOLS.append(compliance_tools.check_compliance)
if calendar_tools.CALENDAR_URL:
    TOOLS.append(calendar_tools.get_calendar_events)


def with_context(prompt, conversation_id):
    timestamp = datetime.now().isoformat(timespec="seconds")
    user_id = conversation_id.split(":")[0]
    return f"[Current date and time: {timestamp}] [UserId: {user_id}]\n{prompt}"


agents = {}


def get_agent(conversation_id, authorization=""):
    if conversation_id not in agents:
        agents[conversation_id] = Agent(
            model=model,
            system_prompt=SYSTEM_PROMPT,
            session_manager=memory_session_manager(conversation_id),
            tools=TOOLS + mcp_tools.user_gateway_tools(authorization),
            callback_handler=None,
        )
        if prompt_config.CONFIG_BUNDLE_ID:
            agents[conversation_id].hooks.add_callback(BeforeModelCallEvent, prompt_config.apply_system_prompt)
    return agents[conversation_id]


@app.entrypoint
async def invoke(payload, context):
    conversation_id = auth.conversation_id(context)
    authorization = (context.request_headers or {}).get("Authorization", "")
    calendar_tools.current_user.set((conversation_id.split(":")[0],
                                     authorization if authorization.startswith("Bearer ") else ""))
    if "oauthSession" in payload:
        calendar_tools.complete_authorization(payload["oauthSession"])
        yield "The corporate calendar is connected. Send your question again."
        return
    agent = get_agent(conversation_id, (context.request_headers or {}).get("Authorization", ""))
    artifacts.current_session.set(conversation_id)
    prompt = with_context(payload["prompt"], conversation_id)
    prompt = guardrail.mask_pii(prompt)
    prompt = attachments.message(prompt, payload)
    async for event in agent.stream_async(prompt):
        if "data" in event:
            yield event["data"]
    files = artifacts.as_markdown(conversation_id)
    if files:
        yield files


app.mount("/", StaticFiles(directory="static", html=True, check_dir=False))

if __name__ == "__main__":
    app.run()
EOF
WS_TEST_BLOCK_1900_8

ws_run_block 9 'Managing the prompt in a configuration bundle' '1. Create PromptConfig.java:' 379 489 'java' 'java-spring-ai' <<'WS_TEST_BLOCK_1900_9'
cat <<'EOF' > ~/environment/aiagent/src/main/java/com/example/agent/PromptConfig.java
package com.example.agent;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;

import org.springaicommunity.agentcore.context.AgentCoreContext;
import org.springframework.ai.chat.client.ChatClientRequest;
import org.springframework.ai.chat.client.ChatClientResponse;
import org.springframework.ai.chat.client.advisor.api.AdvisorChain;
import org.springframework.ai.chat.client.advisor.api.BaseAdvisor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.Ordered;
import org.springframework.stereotype.Component;
import software.amazon.awssdk.core.document.Document;
import software.amazon.awssdk.services.bedrockagentcorecontrol.BedrockAgentCoreControlClient;
import software.amazon.awssdk.services.bedrockagentcorecontrol.model.ComponentConfiguration;

/**
 * Sets the system prompt from the AgentCore configuration bundle before every model call: the latest version, or
 * the version that an A/B test assigns to the session.
 */
@Component
public class PromptConfig implements BaseAdvisor {

    /** Advisor parameter with the request's W3C `baggage` header. */
    static final String BAGGAGE = "baggage";

    private final BedrockAgentCoreControlClient control = BedrockAgentCoreControlClient.create();
    private final String bundleId;
    private final Map<String, String> versionPrompts = new ConcurrentHashMap<>();
    private volatile Instant readAt = Instant.EPOCH;
    private volatile String latestPrompt;

    public PromptConfig(@Value("${app.config-bundle.id}") String bundleId) {
        this.bundleId = bundleId;
    }

    public boolean enabled() {
        return !bundleId.isEmpty();
    }

    static String baggage(AgentCoreContext context) {
        return Objects.requireNonNullElse(context.getHeader(BAGGAGE), "");
    }

    @Override
    public ChatClientRequest before(ChatClientRequest request, AdvisorChain advisorChain) {
        String prompt = variantPrompt((String) request.context().getOrDefault(BAGGAGE, ""));
        if (prompt == null) {
            prompt = latestPrompt();
        }
        if (prompt == null) {
            return request;
        }
        return request.mutate().prompt(request.prompt().augmentSystemMessage(prompt)).build();
    }

    @Override
    public ChatClientResponse after(ChatClientResponse response, AdvisorChain advisorChain) {
        return response;
    }

    @Override
    public int getOrder() {
        return Ordered.HIGHEST_PRECEDENCE;
    }

    private String latestPrompt() {
        if (Duration.between(readAt, Instant.now()).toSeconds() > 60) {
            latestPrompt = systemPrompt(control.getConfigurationBundle(b -> b.bundleId(bundleId)).components());
            readAt = Instant.now();
        }
        return latestPrompt;
    }

    private String variantPrompt(String baggage) {
        Map<String, String> entries = new HashMap<>();
        for (String entry : baggage.split(",")) {
            String[] keyValue = entry.split(";")[0].split("=", 2);
            if (keyValue.length == 2) {
                entries.put(keyValue[0].strip(), URLDecoder.decode(keyValue[1].strip(), StandardCharsets.UTF_8));
            }
        }
        String arn = entries.get("aws.agentcore.configbundle_arn");
        String version = entries.get("aws.agentcore.configbundle_version");
        if (arn == null || version == null) {
            return null;
        }
        return versionPrompts.computeIfAbsent(version, v -> systemPrompt(control.getConfigurationBundleVersion(
            b -> b.bundleId(arn.substring(arn.lastIndexOf('/') + 1)).versionId(v)).components()));
    }

    /** `system_prompt` of the bundle's component (one component per runtime). */
    private static String systemPrompt(Map<String, ComponentConfiguration> components) {
        return components.values().stream().findFirst()
            .map(ComponentConfiguration::configuration)
            .filter(Document::isMap)
            .map(configuration -> configuration.asMap().get("system_prompt"))
            .filter(prompt -> prompt != null && prompt.isString())
            .map(Document::asString)
            .orElse(null);
    }
}
EOF
